INSERT INTO "concepts" ("id","slug","title","body_md","category","has_ui","updated_at") VALUES (1,'project-summary','Project Summary — Skalling v0.11.1','---'||char(10)||'type: Concept'||char(10)||'title: Project Summary — Skalling v0.11.1'||char(10)||'description: Resumen estructural del proyecto skalling-dev-team (8 agentes, scripts bundle, team.db).'||char(10)||'resource: README.md, AGENTS.md, VERSION'||char(10)||'tags: [project-summary, skalling, opencode, agents, teamdb, conventions]'||char(10)||'timestamp: 2026-09-13T13:14:52Z'||char(10)||'agent: pau'||char(10)||'confidence: 0.95'||char(10)||'---'||char(10)||char(10)||'# Project Summary — Skalling v0.11.1'||char(10)||char(10)||'## What'||char(10)||'Equipo de 8 agentes de IA para OpenCode: Alex (orquestador), Pol (spec), Jes (research), Sol (plan), Teo (engineer), Jhon (verifier), Luz (auditor), Pau (memory).'||char(10)||char(10)||'## Stack'||char(10)||'Bash + Python 3, SQLite 3 con FTS5/WAL, OpenCode 1.18.29+. Sin package.json de aplicación — `package.json` solo trae opencode + plugins Node.'||char(10)||char(10)||'## Estructura'||char(10)||'- `scripts/` — bundle canónico (con subdir `lib/`)'||char(10)||'- `scripts/lib/` — helpers compartidos (lib-os.sh, lib-stack-detect.sh, lib-teamdb.sh, lib-memory-check.sh)'||char(10)||'- `tests/` — suite de tests bash/python/js'||char(10)||'- `docs/` — architecture.md, security-model.md'||char(10)||'- `.opencode/` — bundle local (plano, sin subdir lib/) + context (team.db) + agents + skills + changes'||char(10)||'- `sql/` — schemas + migrations'||char(10)||'- `plugins/` — plugins OpenCode (skalling-goal.js, skalling-workflow.js, data-safety)'||char(10)||'- `templates/`, `agents-base/`, `skills-base/`, `constitution/` — fuentes single-source'||char(10)||'- `install-global.sh` — installer a `~/.config/opencode/`'||char(10)||char(10)||'## Versión'||char(10)||'0.11.1 (de VERSION file). Compat: legacy_surface.work_in_progress=read_only_compatibility.'||char(10)||char(10)||'## Convenciones'||char(10)||'- Slugs kebab-case (`auth-jwt`, `stack-postgres`)'||char(10)||'- TeamDB es la fuente: `team.db` (no archivos .md son fuente)'||char(10)||'- Markdown es export derivado (convention docs viven en DB)'||char(10)||'- Escritura SQL parametrizada via `teamdb_exec.py` (R10)'||char(10)||'- Audit log con `actor_source` (helper/trigger/application)'||char(10)||'- Constitución single-source (install-global.sh la renderea a runtime)'||char(10)||'- Cero secretos en DB; destructive operations requieren `teamdb_destructive` con backup','general',0,'2026-09-13 13:46:12');
INSERT INTO "proposals" ("id","slug","title","intent_md","questions_json","status","agent","decided_by","created_at","updated_at","decided_at") VALUES (1,'agentes-db-primera-2026-08-06-legacy-imported','Protocolo DB-primera: agentes consultan team.db antes de leer el proyecto','# Protocolo DB-primera: agentes consultan team.db antes de leer el proyecto'||char(10)||char(10)||'**Slug:** agentes-db-primera-2026-08-06'||char(10)||'**Status:** approved'||char(10)||'**Agent:** pol'||char(10)||'**Fecha:** 2026-08-06 13:19:03'||char(10)||char(10)||'## Contexto'||char(10)||char(10)||'Hoy cuando un usuario pide un plan, los agentes Alex/Pol/Sol/Teo leen 5-10 archivos del proyecto para entender qué existe, en lugar de consultar la tabla concepts de team.db. Aunque hay una regla soft en constitución R14 "consultá la DB primero", no se enforce.'||char(10)||char(10)||'## Causa raíz'||char(10)||char(10)||'Los agentes LLMs ignoran instrucciones narrativas cuando tienen un read/grep tentador disponible. La DB requiere esfuerzo explícito (`teamdb-search.sh "<query>"`), leer un archivo requiere 1 click.'||char(10)||char(10)||'## Decisión'||char(10)||char(10)||'Reemplazamos la sección soft "Grafos del proyecto — cómo y cuándo consultarlos" en los 4 agentes del ciclo SDD (Alex, Pol, Sol, Teo) por un **protocolo numerado concreto**:'||char(10)||char(10)||'1. **Pasos bash numerados**: Paso 1 = `bash teamdb-search.sh "<query>" concept|decision`, Paso 2 = leer `teamdb-related.sh` de slugs relevantes, Paso 3 (opcional) = `curl /api/codegraph`.'||char(10)||'2. **Regla de oro**: si la DB alcanzó, NO leer más.'||char(10)||'3. **CITA obligatoria**: en el artefacto/handoff (proposal.md, tasks.md, commit), el agente debe citar textualmente el resultado de la consulta DB (cuántos concepts, cuántos decisions, qué encontró).'||char(10)||char(10)||'## Tasks completadas'||char(10)||char(10)||'- [x] Reescribir sección de cada agente con protocolo numerado (Teo, 4 agentes)'||char(10)||'- [x] Agregar test FIX 1.3 con 12 asserts en setup.test.sh (Teo)'||char(10)||'- [x] Sincronizar agentes a ~/.config/opencode/agents/ (Teo)'||char(10)||'- [x] Inicializar team.db en meta-proyecto (con backup + dry-run)'||char(10)||'- [x] Persistir propuesta en DB (este INSERT)'||char(10)||char(10)||'## Consecuencias'||char(10)||char(10)||'### Positivas'||char(10)||'- Ahorro de tokens estimado: 60-75% por plan'||char(10)||'- Consistencia: el sistema usa la memoria que ya documentamos'||char(10)||'- Tests verifican que cada agente tiene el protocolo (12 asserts FIX 1.3)'||char(10)||char(10)||'### Negativas / Riesgos'||char(10)||'- Si la DB está vacía, los agentes igualmente intentan leer código (esperado, es el fallback)'||char(10)||'- Tests no garantizan que el LLM siga el protocolo al pie de la letra (es soft-enforcement)'||char(10)||'- Hay 3 menciones de superpowers:* restantes en systematic-debugging/SKILL.md que requieren evaluación caso por caso',NULL,'draft','pol','legacy-import','2026-09-13T13:00:47Z','2026-09-13T13:00:47Z',NULL);
INSERT INTO "proposals" ("id","slug","title","intent_md","questions_json","status","agent","decided_by","created_at","updated_at","decided_at") VALUES (2,'fix-skills-docs-plans-2026-08-06-legacy-imported','Proposal: fix-skills-docs-plans-2026-08-06','<!-- GENERATED from teamdb on 2026-08-06T05:01:40Z. DO NOT EDIT. Source of truth: .opencode/context/team.db.'||char(10)||'     Bidirectional is PROHIBITED. To update DB: sqlite3 $DB (proposals table).'||char(10)||'     To regenerate: bash scripts/teamdb-export-md.sh . -->'||char(10)||char(10)||'# Proposal: fix-skills-docs-plans-2026-08-06'||char(10)||char(10)||'- **Slug:** fix-skills-docs-plans-2026-08-06'||char(10)||'- **Title:** Fix: skills brainstorming y writing-plans deben guardar en DB, no en docs/plans/'||char(10)||'- **Status:** draft'||char(10)||'- **Agent:** pol'||char(10)||'- **Created:** 2026-08-06 05:01:08'||char(10)||char(10)||'## Intent'||char(10)||char(10)||'## Contexto'||char(10)||char(10)||'Las 2 skills copiadas de Superpowers (brainstorming, writing-plans) todavía tienen paths legacy (`docs/plans/`) y referencias externas (`superpowers:*`). El protocolo Skalling v0.7+ exige que TODO se guarde en la DB (`.opencode/context/team.db`) como source of truth, y SOLO se exporte a `.md` cuando es para git legible.'||char(10)||char(10)||'## Causa raíz'||char(10)||char(10)||'- Skills copiadas parcialmente en versiones tempranas'||char(10)||'- Mismo bug que Sol.md/Teo.md tenían pre-0.6.2 (ya parcheado, ver CHANGELOG)'||char(10)||'- Nunca se extendió el fix a las skills'||char(10)||'- Tests/setup.test.sh Tier 1 FIX 1.1 lo valida para agentes pero no para skills'||char(10)||char(10)||'## Solución propuesta'||char(10)||char(10)||'### Skill 1: brainstorming/SKILL.md'||char(10)||'- ELIMINAR: "Write the validated design to `docs/plans/YYYY-MM-DD-<topic>-design.md`"'||char(10)||'- ELIMINAR: refs a `superpowers:using-git-worktrees`, `superpowers:writing-plans`'||char(10)||'- REEMPLAZAR por: "Pol devuelve proposal validado a Alex. Source of truth: tabla `proposals` en team.db (vía `teamdb_write_project`). El export `.md` se genera on-demand con `teamdb_export_md`, no es storage primario."'||char(10)||char(10)||'### Skill 2: writing-plans/SKILL.md'||char(10)||'- ELIMINAR: refs a `docs/plans/` (líneas 18, 101)'||char(10)||'- ELIMINAR: refs a `superpowers:*` (líneas 36, 110, 116)'||char(10)||'- REEMPLAZAR por: "Sol escribe `design.md` y `tasks.md` después de INSERT en DB vía `teamdb-plan.sh`. Source of truth: tabla `plans` + `tasks` en team.db."'||char(10)||char(10)||'### Tests nuevos (en tests/setup.test.sh)'||char(10)||'- `test_skills_no_docs_plans`: assert NO `docs/plans` en ninguna SKILL.md'||char(10)||'- `test_skills_no_superpowers`: assert NO `superpowers:` (excepto whitelist explícita)'||char(10)||'- `test_brainstorming_uses_db`: assert que menciona `team.db` o `teamdb_write_project`'||char(10)||char(10)||'## Tasks'||char(10)||char(10)||'- [ ] Reescribir brainstorming/SKILL.md'||char(10)||'- [ ] Reescribir writing-plans/SKILL.md'||char(10)||'- [ ] Agregar 3 tests en tests/setup.test.sh'||char(10)||'- [ ] Correr `bash install-global.sh --force` para distribuir'||char(10)||'- [ ] Verificar que ningún proyecto use el path legacy'||char(10)||char(10)||'## Consecuencias'||char(10)||char(10)||'### Positivas'||char(10)||'- TODO el flujo de brainstorming va a la DB, no al filesystem'||char(10)||'- Consistencia con el resto del sistema'||char(10)||'- Rastreable, versionado, auditable'||char(10)||'- Backup automático ya aplica (v0.7.6)'||char(10)||char(10)||'### Negativas / Riesgos'||char(10)||'- Si algún proyecto cliente tiene archivos en `docs/plans/` viejos, hay que migrarlos manualmente con `teamdb-plan.sh` por cada uno'||char(10)||'- Hay 3 menciones de `superpowers:` en `systematic-debugging/SKILL.md` que hay que evaluar caso por caso'||char(10)||char(10)||'## Related'||char(10)||char(10)||'- CHANGELOG 0.6.2: fix similar aplicado a Sol.md/Teo.md'||char(10)||'- tests/setup.test.sh FIX 1.1: patrón Tier 1 a replicar'||char(10)||'- constitution R6: ubicación canónica `.opencode/changes/<feature-slug>/`'||char(10)||char(10)||char(10)||'<!-- Footer: regenerar desde DB con scripts/teamdb-export-md.sh -->',NULL,'draft','pol','legacy-import','2026-09-13T13:00:47Z','2026-09-13T13:00:47Z',NULL);
INSERT INTO "proposals" ("id","slug","title","intent_md","questions_json","status","agent","decided_by","created_at","updated_at","decided_at") VALUES (3,'plan-unico-versionado-2026-08-06-legacy-imported','Plan único versionado: 1 proposal → 1 plan → N tasks ejecutables, todo en DB','# Plan único versionado: 1 proposal → 1 plan → N tasks ejecutables, todo en DB'||char(10)||char(10)||'**Slug:** plan-unico-versionado-2026-08-06'||char(10)||'**Status:** approved'||char(10)||'**Agent:** pol'||char(10)||'**Fecha:** 2026-08-06 12:00:00'||char(10)||char(10)||'## Contexto'||char(10)||char(10)||'Hoy, cuando un usuario pide un plan, el sistema produce artefactos redundantes y contradictorios:'||char(10)||char(10)||'1. **Dos planes paralelos por feature**. Pol escribe `proposal.md` (validación ligera del intent). Sol escribe `design.md` + `tasks.md` (plan técnico detallado). Ambos viven en `.opencode/changes/<slug>/` como archivos separados. Si Teo los lee, ve DOS documentos distintos sobre el mismo tema y no sabe cuál seguir.'||char(10)||char(10)||'2. **Tasks con títulos poéticos**. Las tasks que escribe Sol tienen nombres tipo "Gimme Shelter", "Sympathy for the Devil". Sin propósito explícito, sin criterios de aceptación verificables, sin orden lógico que indique qué bloquea qué.'||char(10)||char(10)||'3. **Sol CREA OTRO PLAN en vez de mejorar el existente**. Cuando el `proposal.md` necesita más detalle técnico, Sol abre `design.md` aparte en lugar de hacer UPDATE del mismo plan en la DB. Resultado: dos documentos divergentes sobre la misma feature.'||char(10)||char(10)||'4. **Teo se inventa planes**. Cuando va a ejecutar, en vez de consultar la DB por el plan activo del slug y seguirlo, a veces inventa su propio approach basándose en lo que vio en el `proposal.md` + `design.md` + su propio instinto.'||char(10)||char(10)||'5. **Dos sources of truth**. Las tasks existen en archivos `.md` Y en la tabla `tasks` de `team.db`. Si editás uno, el otro queda stale. No hay garantía de que lo que Teo ejecuta coincida con lo que el humano aprobó.'||char(10)||char(10)||'## Causa raíz'||char(10)||char(10)||'El modelo actual es **filesystem-first**: el ciclo de un plan vive en archivos `.md` bajo `.opencode/changes/<slug>/`. La DB tiene las tablas (`proposals`, `plans`, `tasks`, `task_dependencies`, `plan_history`) pero los agentes no las usan como contrato — las usan como espejo opcional.'||char(10)||char(10)||'Síntomas estructurales:'||char(10)||char(10)||'- **Falta enforcement de "1 plan por slug activo"**. `plans.slug` es `UNIQUE`, pero nada impide que haya un plan `draft` y otro `active` para el mismo slug simultáneamente. `teamdb-plan.sh` resuelve esto parcialmente con `ON CONFLICT(slug) DO UPDATE`, pero no hay check explícito.'||char(10)||'- **No hay lifecycle formal**. `plans.status` acepta `draft|active|completed|abandoned`. Falta `in_progress` y `approved` para representar el flujo real (Pol escribe proposal → user aprueba → Sol mejora → Teo ejecuta → complete).'||char(10)||'- **`tasks.purpose` no existe**. Solo hay `title` + `description_md`. Los criterios de aceptación van en `acceptance_md` pero no se enforce que estén presentes.'||char(10)||'- **`tasks.depends_on` no existe como JSON**. Está la tabla `task_dependencies` (mejor diseño relacional, de hecho), pero no se usa en `teamdb-plan.sh` consistentemente para visualizar el DAG.'||char(10)||'- **`plans.intent_md` no existe**. Solo `design_md`. La intención validada por Pol queda huérfana del plan una vez que Sol lo "toma".'||char(10)||'- **`plans.version` no existe**. `plan_history` tiene `version` pero `plans` no. Imposible hacer "última versión" sin joins.'||char(10)||char(10)||'## Decisión'||char(10)||char(10)||'**Un solo plan semántico por feature-slug, viviendo en la DB. Los archivos `.md` son SOLO exports legibles para git, no contratos.**'||char(10)||char(10)||'### Reglas duras'||char(10)||char(10)||'1. **1 plan por feature-slug**. Constraint: `UNIQUE(slug WHERE status IN (''draft'',''approved'',''in_progress''))` — solo puede haber UNO activo a la vez. Si se quiere un nuevo intento, el viejo pasa a `abandoned` (no se borra; queda en `audit_log`).'||char(10)||'2. **Source of truth = DB**. El artefacto canónico es la fila de la tabla (`proposals`, `plans`, `tasks`). El `.md` en `.opencode/changes/<slug>/` se regenera con `teamdb-export-md.sh` y SIEMPRE lleva header `<!-- GENERATED -->`. Editar el `.md` está prohibido y se detecta con diff contra la DB.'||char(10)||'3. **Lifecycle explícito**: `draft → approved → in_progress → completed`. Transiciones registradas en `audit_log` (ya hay triggers en `tasks`, falta en `plans`).'||char(10)||'4. **Pol escribe el `proposal`** (intención validada, no muy detallado). Status inicial: `draft`.'||char(10)||'5. **Sol hace UPDATE del mismo plan**, no crea otro. Cuando necesita más detalle técnico, edita `plans.design_md` + agrega `specs` + `design_notes`. El plan pasa a `approved` cuando Pol/user lo firma.'||char(10)||'6. **Pol NO borra el plan de Sol**. Solo puede agregar otra versión (incrementar `plans.version`, append a `plan_history` con `operation=''amended''`).'||char(10)||'7. **Teo busca el plan activo por slug en la DB y lo sigue**. Comando: `teamdb-execute-plan.sh <project> --slug=<slug>`. NO inventa otro. NO lee `.md` para "interpretar".'||char(10)||'8. **Tasks con contrato**: cada task tiene `purpose` (1-2 frases por qué existe) + `acceptance_md` (criterios verificables) + `order_index` (entero, orden de ejecución) + DAG via `task_dependencies` (FK a otras tasks del mismo plan). Títulos NO poéticos: `"Migrar plans.design_md a nullable"` no `"Gimme Shelter"`.'||char(10)||char(10)||'### Responsabilidades por agente'||char(10)||char(10)||'| Agente | Responsabilidad | Acción sobre la DB |'||char(10)||'|---|---|---|'||char(10)||'| **Pol** | Validar intent, escribir `proposal` | `INSERT proposals(status=''draft'')`. No toca `plans`. |'||char(10)||'| **Sol** | Mejorar plan técnico, definir tasks | `UPDATE plans(design_md, version+=1)`, `INSERT specs`, `INSERT tasks`, `INSERT task_dependencies`. Status: `draft → approved`. |'||char(10)||'| **Teo** | Ejecutar tasks | `SELECT tasks WHERE plan_id=? ORDER BY order_index`, claim con `task_claims`, `UPDATE tasks(status=''in_progress'')`. |'||char(10)||'| **Luz** | Verificar AC de cada task | `UPDATE tasks(status=''in_review'', resolution_md=''...'')`. |'||char(10)||'| **Pau** | Cerrar feature | `UPDATE plans(status=''completed'')` cuando todas las tasks están `approved`. |'||char(10)||char(10)||'### Schema propuesto (migration 009)'||char(10)||char(10)||'> **Nota técnica**: las tablas `plans` y `tasks` YA EXISTEN (migration 002, schema v0.7.1). El approach es **ALTER TABLE** + nuevas constraints, NO `CREATE TABLE` (eso borraría data existente).'||char(10)||char(10)||'```sql'||char(10)||'-- 009_unique_plan_active.sql'||char(10)||'PRAGMA foreign_keys=OFF;'||char(10)||'BEGIN TRANSACTION;'||char(10)||char(10)||'-- 1. plans: agregar columnas faltantes'||char(10)||'CREATE TABLE plans_new ('||char(10)||'  id INTEGER PRIMARY KEY,'||char(10)||'  slug TEXT UNIQUE NOT NULL,'||char(10)||'  title TEXT NOT NULL,'||char(10)||'  proposal_id INTEGER REFERENCES proposals(id),'||char(10)||'  intent_md TEXT,                          -- NUEVO: copia del proposal.intent_md al crear el plan'||char(10)||'  design_md TEXT NOT NULL DEFAULT '''','||char(10)||'  acceptance_md TEXT,'||char(10)||'  status TEXT DEFAULT ''draft'' CHECK(status IN (''draft'',''approved'',''in_progress'',''completed'',''abandoned'')),'||char(10)||'  version INTEGER DEFAULT 1,               -- NUEVO'||char(10)||'  agent TEXT,'||char(10)||'  created_at TEXT,'||char(10)||'  updated_at TEXT,'||char(10)||'  completed_at TEXT,'||char(10)||'  created_by TEXT,                         -- NUEVO'||char(10)||'  updated_by TEXT                          -- NUEVO'||char(10)||');'||char(10)||char(10)||'INSERT INTO plans_new (id, slug, title, proposal_id, intent_md, design_md, acceptance_md,'||char(10)||'                       status, agent, created_at, updated_at, completed_at, version)'||char(10)||'SELECT id, slug, title, proposal_id, NULL AS intent_md, design_md, acceptance_md,'||char(10)||'       status, agent, created_at, updated_at, completed_at, 1 AS version'||char(10)||'FROM plans;'||char(10)||char(10)||'DROP TABLE plans;'||char(10)||'ALTER TABLE plans_new RENAME TO plans;'||char(10)||'CREATE INDEX idx_plans_status ON plans(status);'||char(10)||char(10)||'-- 2. tasks: agregar purpose (description_md se mantiene como legacy/extended)'||char(10)||'CREATE TABLE tasks_new ('||char(10)||'  id INTEGER PRIMARY KEY,'||char(10)||'  plan_id INTEGER NOT NULL REFERENCES plans(id),'||char(10)||'  slug TEXT NOT NULL,'||char(10)||'  title TEXT NOT NULL,'||char(10)||'  purpose TEXT NOT NULL DEFAULT '''',        -- NUEVO: por qué existe (1-2 frases)'||char(10)||'  description_md TEXT,                     -- LEGACY: detalles extendidos, opcional'||char(10)||'  acceptance_md TEXT NOT NULL DEFAULT '''',  -- ENFORCE: obligatorio (CHECK en aplicación)'||char(10)||'  status TEXT DEFAULT ''pending'' CHECK(status IN (''pending'',''in_progress'',''in_review'',''approved'',''resolved'',''rejected'',''blocked'')),'||char(10)||'  priority INTEGER DEFAULT 3,'||char(10)||'  owner TEXT,'||char(10)||'  blocked_reason TEXT,'||char(10)||'  resolution_md TEXT,'||char(10)||'  order_index INTEGER DEFAULT 0,'||char(10)||'  estimated_minutes INTEGER,'||char(10)||'  created_at TEXT,'||char(10)||'  updated_at TEXT,'||char(10)||'  started_at TEXT,'||char(10)||'  resolved_at TEXT,'||char(10)||'  UNIQUE(plan_id, slug)'||char(10)||');'||char(10)||char(10)||'INSERT INTO tasks_new (id, plan_id, slug, title, purpose, description_md, acceptance_md,'||char(10)||'                       status, priority, owner, blocked_reason, resolution_md,'||char(10)||'                       order_index, estimated_minutes, created_at, updated_at, started_at, resolved_at)'||char(10)||'SELECT id, plan_id, slug, title, '''' AS purpose, description_md, COALESCE(acceptance_md, ''''),'||char(10)||'       status, priority, owner, blocked_reason, resolution_md,'||char(10)||'       order_index, estimated_minutes, created_at, updated_at, started_at, resolved_at'||char(10)||'FROM tasks;'||char(10)||char(10)||'DROP TABLE tasks;'||char(10)||'ALTER TABLE tasks_new RENAME TO tasks;'||char(10)||'CREATE INDEX idx_tasks_plan ON tasks(plan_id);'||char(10)||'CREATE INDEX idx_tasks_status ON tasks(status);'||char(10)||'CREATE INDEX idx_tasks_owner ON tasks(owner);'||char(10)||char(10)||'-- 3. Audit triggers en plans (ya existen en tasks, work_in_progress, etc.)'||char(10)||'CREATE TRIGGER plans_audit_ai AFTER INSERT ON plans BEGIN'||char(10)||'  INSERT INTO audit_log (ts, agent, action, table_name, row_id, details, actor_source)'||char(10)||'  VALUES (datetime(''now''), ''system'', ''insert'', ''plans'', new.id,'||char(10)||'          json_object(''slug'', new.slug, ''status'', new.status), ''trigger'');'||char(10)||'END;'||char(10)||'CREATE TRIGGER plans_audit_au AFTER UPDATE ON plans BEGIN'||char(10)||'  INSERT INTO audit_log (ts, agent, action, table_name, row_id, details, actor_source)'||char(10)||'  VALUES (datetime(''now''), ''system'', ''update'', ''plans'', new.id,'||char(10)||'          json_object(''slug'', new.slug, ''old_status'', old.status, ''new_status'', new.status, ''version'', new.version), ''trigger'');'||char(10)||'END;'||char(10)||char(10)||'COMMIT;'||char(10)||'PRAGMA foreign_keys=ON;'||char(10)||char(10)||'UPDATE schema_meta SET value = ''0.7.7'' WHERE key = ''version'';'||char(10)||'```'||char(10)||char(10)||'### Cambios en scripts'||char(10)||char(10)||'| Script | Cambio |'||char(10)||'|---|---|'||char(10)||'| `teamdb-plan.sh` | Al crear plan, copiar `proposal.intent_md` → `plan.intent_md`. Al insertar task, exigir `purpose` no vacío + `acceptance_md` no vacío (fail-fast con mensaje claro). |'||char(10)||'| `teamdb-amend.sh` | Nuevo: UPDATE del plan existente (incrementa `version`, append a `plan_history` con `operation=''amended''`). |'||char(10)||'| `teamdb-plan.sh` (subcomando) | Agregar `--improve` para que Sol pueda llamar al mismo script en modo UPDATE, no solo CREATE. |'||char(10)||'| `teamdb-export-md.sh` | Refrescar header: incluir `purpose` de cada task en `tasks.md`, no solo título. |'||char(10)||'| `teamdb-execute-plan.sh` | Si el plan está en `draft`, abortar con error claro: "Plan no aprobado. Status actual: draft. Necesita status=''approved'' para ejecutar." |'||char(10)||char(10)||'### Cambios en agentes (protocol)'||char(10)||char(10)||'| Agente | Cambio |'||char(10)||'|---|---|'||char(10)||'| `agents-base/Pol.md` | Regla: "NO escribir archivos `.md` de plan. SOLO INSERT en `proposals`. El `.md` se regenera con `teamdb-export-md.sh`." |'||char(10)||'| `agents-base/Sol.md` | Regla: "Cuando recibís un handoff de Pol con `proposal.status=''approved''`, hacés UPDATE del plan existente (`teamdb-amend.sh`), NO creás otro. Incrementás `version`. Si necesitás romper compatibilidad, creás un plan nuevo con `status=''draft''` y el viejo pasa a `abandoned`." |'||char(10)||'| `agents-base/Teo.md` | Regla: "Antes de ejecutar, `teamdb-execute-plan.sh <project> --slug=<slug>`. Si no hay plan activo, ABORT y escalar a Alex. NO inventar plan propio." |'||char(10)||'| `agents-base/Luz.md` | Regla: "Verificás cada task contra su `acceptance_md`. Si pasa, marcás `status=''approved''` + `resolution_md` con evidencia. Si falla, `status=''rejected''` + razón." |'||char(10)||'| `agents-base/Alex.md` | Regla: "Cuando derive a Sol, pasá el `proposal_id` o `plan_id` (no el path al `.md`). Sol lee la DB, no el filesystem." |'||char(10)||char(10)||'### Cambios en skills'||char(10)||char(10)||'| Skill | Cambio |'||char(10)||'|---|---|'||char(10)||'| `skills-base/writing-plans/SKILL.md` | Reescribir para que use `teamdb-plan.sh --improve` y `teamdb-amend.sh`. Eliminar refs a `docs/plans/` o `.opencode/changes/<slug>/design.md` como artefactos primarios. |'||char(10)||'| `skills-base/brainstorming/SKILL.md` | Reforzar: el output es INSERT en `proposals`, no archivo. |'||char(10)||char(10)||'## Tasks (ordenadas, con propósito + AC)'||char(10)||char(10)||'### Task 1: Crear migration 009_unique_plan_active.sql'||char(10)||'- **purpose**: Permitir el nuevo lifecycle (`approved`, `in_progress`) y agregar columnas `version`, `intent_md`, `created_by`, `updated_by` en `plans`, y `purpose` en `tasks`, sin romper data existente (ALTER TABLE pattern).'||char(10)||'- **acceptance_criteria**:'||char(10)||'  - [ ] Archivo `sql/migrations/009_unique_plan_active.sql` existe y es idempotente'||char(10)||'  - [ ] `bash scripts/teamdb-migrate.sh .` corre sin errores sobre una DB con plans/tasks previos'||char(10)||'  - [ ] `teamdb_exec_query .opencode/context/team.db "PRAGMA table_info(plans)"` muestra columnas `intent_md`, `version`, `created_by`, `updated_by`'||char(10)||'  - [ ] `teamdb_exec_query .opencode/context/team.db "PRAGMA table_info(tasks)"` muestra columna `purpose`'||char(10)||'  - [ ] Audit triggers sobre `plans` existen (`SELECT name FROM sqlite_master WHERE type=''trigger'' AND tbl_name=''plans''`)'||char(10)||'  - [ ] `schema_meta.version = ''0.7.7''`'||char(10)||'- **depends_on**: —'||char(10)||char(10)||'### Task 2: Actualizar agents-base/Pol.md (no crear archivos de plan)'||char(10)||'- **purpose**: Eliminar la tentación de Pol de crear `proposal.md` directamente en `.opencode/changes/<slug>/` cuando arranca un plan.'||char(10)||'- **acceptance_criteria**:'||char(10)||'  - [ ] Sección "Protocolo DB-primera" en Pol.md menciona explícitamente: "NO escribir `.opencode/changes/<slug>/proposal.md`"'||char(10)||'  - [ ] Comando canónico documentado: `teamdb-plan.sh <project> create <slug> <title> --intent-stdin`'||char(10)||'  - [ ] Test en `tests/setup.test.sh`: `test_pol_no_md_writes` (busca patrones `write.*\.opencode/changes/.*proposal\.md` en Pol.md → debe dar 0)'||char(10)||'  - [ ] Sincronizado a `~/.config/opencode/agents/Pol.md`'||char(10)||'- **depends_on**: Task 1'||char(10)||char(10)||'### Task 3: Actualizar agents-base/Sol.md (UPDATE no CREATE)'||char(10)||'- **purpose**: Forzar que Sol mejore el plan existente (UPDATE) en lugar de abrir `design.md` aparte.'||char(10)||'- **acceptance_criteria**:'||char(10)||'  - [ ] Sección "Mejorar plan, no crear otro" en Sol.md menciona: "Cuando `proposals.status=''approved''`, usar `teamdb-amend.sh`, NO `teamdb-plan.sh create`"'||char(10)||'  - [ ] Comando documentado: `teamdb-amend.sh <project> --slug=<slug> --design-stdin --add-task=<task.json>`'||char(10)||'  - [ ] Test: `test_sol_uses_amend` (busca `teamdb-amend.sh` en Sol.md → debe aparecer ≥1 vez)'||char(10)||'  - [ ] Sincronizado a `~/.config/opencode/agents/Sol.md`'||char(10)||'- **depends_on**: Task 1'||char(10)||char(10)||'### Task 4: Actualizar agents-base/Teo.md (lee DB, no inventa)'||char(10)||'- **purpose**: Que Teo consulte el plan activo por slug antes de ejecutar, en vez de improvisar.'||char(10)||'- **acceptance_criteria**:'||char(10)||'  - [ ] Sección "Pre-ejecución" en Teo.md: "Paso 1: `teamdb-execute-plan.sh <project> --slug=<slug> --dry-run`. Si retorna error ''no active plan'', ABORT."'||char(10)||'  - [ ] Comando `teamdb-execute-plan.sh` rechazada ejecución si `plans.status NOT IN (''approved'',''in_progress'')`'||char(10)||'  - [ ] Test: `test_teo_queries_db_first` (assert Teo.md contiene `teamdb-execute-plan.sh`)'||char(10)||'  - [ ] Sincronizado a `~/.config/opencode/agents/Teo.md`'||char(10)||'- **depends_on**: Task 1, Task 3'||char(10)||char(10)||'### Task 5: Extender teamdb-plan.sh + crear teamdb-amend.sh'||char(10)||'- **purpose**: Dar herramientas bash que enforce "1 plan por slug" y "tasks con purpose+AC".'||char(10)||'- **acceptance_criteria**:'||char(10)||'  - [ ] `teamdb-plan.sh create`: al crear plan, copia `proposal.intent_md` → `plan.intent_md`. Si task no tiene `purpose` o `acceptance_md`, falla con mensaje claro: "task ''<slug>'' sin purpose o acceptance_md"'||char(10)||'  - [ ] `teamdb-amend.sh <project> --slug=<slug>`: hace UPDATE del plan, incrementa `version`, append a `plan_history` con `operation=''amended''`'||char(10)||'  - [ ] `teamdb-amend.sh --add-task=<task.json>`: inserta task en plan existente con validación de purpose/AC'||char(10)||'  - [ ] Tests: `test_plan_create_copies_intent`, `test_amend_increments_version`, `test_amend_appends_history`'||char(10)||'- **depends_on**: Task 1'||char(10)||char(10)||'### Task 6: Tests FIX 1.4 (invariantes "1 plan por slug" + "tasks con propósito+AC")'||char(10)||'- **purpose**: Que el sistema falle rápido si alguien rompe los invariantes.'||char(10)||'- **acceptance_criteria**:'||char(10)||'  - [ ] Test `test_one_active_plan_per_slug`: insertar 2 plans con mismo slug + status activo → debe fallar por UNIQUE constraint'||char(10)||'  - [ ] Test `test_task_requires_purpose`: insertar task sin purpose → debe fallar'||char(10)||'  - [ ] Test `test_task_requires_acceptance`: insertar task sin acceptance_md → debe fallar'||char(10)||'  - [ ] Test `test_plan_lifecycle_transitions`: `draft → approved → in_progress → completed` permitido; `draft → completed` directo NO permitido (validar via trigger o CHECK)'||char(10)||'  - [ ] Test `test_md_is_generated`: `.opencode/changes/<slug>/proposal.md` lleva header `<!-- GENERATED -->`'||char(10)||'  - [ ] Todos los tests pasan con `bash tests/setup.test.sh`'||char(10)||'- **depends_on**: Task 1, Task 5'||char(10)||char(10)||'### Task 7: Skill writing-plans (reescribir para usar teamdb)'||char(10)||'- **purpose**: Que la skill enseñe el flujo nuevo, no el viejo de escribir `.md`.'||char(10)||'- **acceptance_criteria**:'||char(10)||'  - [ ] `skills-base/writing-plans/SKILL.md` menciona `teamdb-plan.sh` y `teamdb-amend.sh` con ejemplos concretos'||char(10)||'  - [ ] NO contiene `docs/plans/` ni `.opencode/changes/<slug>/design.md` como paths primarios'||char(10)||'  - [ ] Paso "Output" del workflow dice: "INSERT en `proposals` (status=''draft''). El export `.md` es secundario."'||char(10)||'  - [ ] Sincronizado a `~/.config/opencode/skills/writing-plans/SKILL.md`'||char(10)||'- **depends_on**: Task 5'||char(10)||char(10)||'### Task 8: Migrar planes `.md` viejos a la DB'||char(10)||'- **purpose**: Eliminar la dualidad source-of-truth para planes existentes.'||char(10)||'- **acceptance_criteria**:'||char(10)||'  - [ ] Script `scripts/migrate-md-plans-to-db.sh` lee `.opencode/changes/<slug>/proposal.md` + `design.md` + `tasks.md`, INSERT en DB'||char(10)||'  - [ ] Si ya existe plan con ese slug en DB, skip + warning'||char(10)||'  - [ ] Backup del filesystem antes (`mv .opencode/changes .opencode/changes.bak.$(date +%Y%m%d)`)'||char(10)||'  - [ ] Reporte: cuántos planes migrados, cuántos saltados'||char(10)||'  - [ ] Run sobre el meta-proyecto: 0 errores, N migrados'||char(10)||'- **depends_on**: Task 1, Task 5'||char(10)||char(10)||'## Consecuencias'||char(10)||char(10)||'### Positivas'||char(10)||char(10)||'- **1 source of truth** para planes y tasks. La DB es el contrato; el `.md` es solo legible.'||char(10)||'- **Lifecycle explícito y auditable**. `audit_log` registra cada transición `draft → approved → in_progress → completed`. Reproducible.'||char(10)||'- **Tasks ejecutables con criterios verificables**. `purpose` + `acceptance_md` obligatorios eliminan el "qué significa hecho?" al momento de Luz verificar.'||char(10)||'- **Versionado real**. `plans.version` + `plan_history` permiten ver la evolución sin git archaeology.'||char(10)||'- **DAG explícito**. `task_dependencies` (ya existe) permite a Teo ejecutar en orden topológico, no adivinando.'||char(10)||'- **Migración al modelo DB-first completa**. Esta propuesta cierra el ciclo abierto por `agentes-db-primera-2026-08-06` y `fix-skills-docs-plans-2026-08-06`.'||char(10)||char(10)||'### Negativas / Riesgos'||char(10)||char(10)||'- **Migración de planes `.md` viejos**. Hay planes existentes en `.opencode/changes/` que deben moverse a la DB (Task 8). Riesgo: si un plan tiene un `.md` desactualizado respecto a la DB, hay que decidir cuál gana.'||char(10)||'- **Breaking change en scripts que asumen schema viejo**. Si algún cliente externo lee `team.db` directo y asume que `plans` no tiene `intent_md`, va a fallar. Mitigación: el campo se agrega como nullable, no rompe queries existentes.'||char(10)||'- **Curva de aprendizaje**. Sol y Teo tienen que aprender el nuevo flujo (`teamdb-amend.sh` en vez de "abrir otro archivo"). Mitigación: tests FIX 1.4 + skill writing-plans reescrita.'||char(10)||'- **Performance del ALTER TABLE**. Para DBs con miles de plans, recrear la tabla toma segundos. Aceptable para meta-proyecto (decenas de planes), problemático para proyectos grandes. Mitigación: si el proyecto tiene >1000 plans, agregar flag `--no-rebuild` que haga ALTER TABLE ADD COLUMN en vez de recreate (SQLite soporta ALTER ADD COLUMN, no DROP COLUMN).'||char(10)||char(10)||'### Related'||char(10)||char(10)||'- `agentes-db-primera-2026-08-06`: ciclo DB-primera en agents-base (predecesor)'||char(10)||'- `fix-skills-docs-plans-2026-08-06`: fix de skills brainstorming/writing-plans (predecesor paralelo)'||char(10)||'- constitution R6: ubicación canónica `.opencode/changes/<feature-slug>/` (mantener para exports)'||char(10)||'- constitution R14: "consultá la DB primero" (esta propuesta la enforce en planes)'||char(10)||'- schema v0.7.6 → v0.7.7 (migration 009)'||char(10)||char(10)||'---'||char(10)||char(10)||'<!-- Footer: regenerar desde DB con teamdb-export-md.sh -->',NULL,'draft','pol','legacy-import','2026-09-13T13:00:47Z','2026-09-13T13:00:47Z',NULL);
INSERT INTO "proposals" ("id","slug","title","intent_md","questions_json","status","agent","decided_by","created_at","updated_at","decided_at") VALUES (4,'sqli-remediation-phase3','Fase 3 Remediacion SQLi Skalling','# Intent'||char(10)||char(10)||'Fase 3 Remediacion SQLi Skalling',NULL,'draft','pol',NULL,'2026-09-13T13:39:31Z','2026-09-13T13:39:31Z',NULL);
INSERT INTO "proposals" ("id","slug","title","intent_md","questions_json","status","agent","decided_by","created_at","updated_at","decided_at") VALUES (5,'scripts-parity-phase2','Paridad bundle-local .opencode/scripts/ vs fuente scripts/','# Intent'||char(10)||char(10)||'Paridad bundle-local .opencode/scripts/ vs fuente scripts/',NULL,'draft','pol',NULL,'2026-09-13T13:40:54Z','2026-09-13T13:40:54Z',NULL);
INSERT INTO "plans" ("id","slug","title","proposal_id","design_md","acceptance_md","status","agent","created_at","updated_at","completed_at","intent_md","version","created_by","updated_by") VALUES (1,'sqli-remediation-phase3','Fase 3 Remediacion SQLi Skalling',4,'Fase 3 del plan de remediacion SQLi. Auditoria estatica de 12 sitios sospechosos en scripts/*.sh contra los patrones pat_sqli y pat_sqli_dq de skalling-review.sh (líneas 447-491). Resultado: 0 sitios VULNERABLES en producción; 10 sitios clasificados como SEGURO-LITERAL o SEGURO-WHITELIST (sin variables del usuario en queries); 1 sitio ya usa _sql_quote (teamdb-attempt.sh:226, falso positivo del grep); 2 sitios usan escape manual con sed y se migran a teamdb_exec_value por consistencia y defensa en profundidad (wip-tree.sh:43, migrate-plans-md-to-db.sh:161). Estrategia de hardening: (1) centralizar lista de excepciones del linter con justificación inline en skalling-review.sh; (2) nuevo workflow .github/workflows/lint-sqli.yml que corre el linter sobre scripts/** excluyendo archivos exceptuados, falla si detecta pat_sqli o pat_sqli_dq, se dispara en push/PR a main y develop; (3) migrar los 2 sitios a teamdb_exec_value con bind params reales; (4) tests SQLi nuevos tests/teamdb-wip-tree-sqli.test.sh y tests/migrate-plans-sqli.test.sh que validan no-destrucción de tablas con payload SQLi; (5) integrar nuevos tests en teamdb-hardening-suite.sh; (6) documentar en MEMORY la decisión de mantener git-gate.py pre-push sin invocar skalling-review.sh (separación de scope: lint es CI, secretos/memDB/receipt son push).','Plan persistido con 9 tasks (1 raíz independiente, 1 fan-out, 3 paralelas, 1 fan-in, 1 paralelo adicional, 1 cierre) y 11 edges acíclicos. Cero sitios VULNERABLES en scripts/ post-migración. Lint CI activo en .github/workflows/lint-sqli.yml con lista de excepciones documentada (lib-teamdb.sh = provee helpers; skalling-review.sh = los busca; teamdb_exec.py = binding real; tests/** = fixtures). wip-tree.sh:43 y migrate-plans-md-to-db.sh:161 migrados a teamdb_exec_value con bind params Python (real parameter binding, no escape manual). Tests SQLi nuevos verdes (tests/teamdb-wip-tree-sqli.test.sh y tests/migrate-plans-sqli.test.sh) y agregados al listado de tests/teamdb-hardening-suite.sh. Decisión pre-push documentada en MEMORY (slugs y racional). Receipt final sellado por Pau con verificación de lint CI falla con caso sintético y árbol de tasks approved/resolved.'||char(10)||char(10)||'Referencia de alcance/aprobación: Pedido del usuario: req-20260913101348-44357, risk=medium, alcance explícito: auditoría sitios listados (teamdb-link.sh:54, teamdb-context-cache.sh:19, teamdb-export-md.sh:74, teamdb-skills-sync.sh:94, teamdb-migrate.sh:42, teamdb-restore.sh:105, skalling-metrics.sh:36/40, teamdb-attempt.sh:226 + wip-tree.sh:43 y migrate-plans-md-to-db.sh:161 que aparecieron durante la auditoría), plan DB-first con lista categorizada, spec linter CI bloqueante, plan migración por sitio, tests nuevos para gaps. Usuario explícitamente prohibió implementación y modificación de archivos del repo.','approved','sol','2026-09-13T13:39:31Z','2026-09-13 13:45:07',NULL,'# Intent'||char(10)||char(10)||'Fase 3 Remediacion SQLi Skalling',2,'sol','sol');
INSERT INTO "plans" ("id","slug","title","proposal_id","design_md","acceptance_md","status","agent","created_at","updated_at","completed_at","intent_md","version","created_by","updated_by") VALUES (2,'scripts-parity-phase2','Paridad bundle-local .opencode/scripts/ vs fuente scripts/',5,'Estrategia: paridad semántica con manifest explícito scripts/.bundle-manifest (formato TSV src<tab>dst) que define el mapping src→dst para el bundle local. scripts/build-local-snapshot.sh implementa tres modos: --apply (idempotente, copia atómica vía tmp+rename, preserva permisos con cp -p), --check (diff byte-a-byte con shasum, exit≠0 si drift), --dry-run (imprime plan de acción). El manifest incluye: scripts/skalling-*.sh→.opencode/scripts/skalling-*.sh (1:1), scripts/teamdb-*.sh→1:1, scripts/{dashboard-server,skalling-workflow,teamdb_exec,teamdb_guard,teamdb-destructive}.py→1:1, scripts/{mem-review,spec-memory-link,merge-helper,update,wip-tree,build-schema}.sh→1:1, scripts/lib/lib-{os,stack-detect,teamdb}.sh→.opencode/scripts/lib-{os,stack-detect,teamdb}.sh (aplanización lib/→plano intencional por compatibilidad con permisos de agentes y rutas usadas en runtime). Ignorados: __pycache__/, hooks/ (separado), lib-memory-check.sh (helper sourced, no ejecutable bundle), render-agent.sh y permission-policy.py (build tools), migrate-* (legacy), test-teamdb-*.sh (tests internos). tests/scripts-parity.test.sh ejecuta --check en sandbox y exige exit 0; verifica que cada archivo del manifest existe en destino con hash idéntico y que NO hay huérfanos en .opencode/scripts/ (whitelist de permitidos). setup-team-doctor.sh gana check_scripts_parity que invoca --check y emite warn/info según modo; con --strict promueve a error. .github/workflows/tests.yml agrega el test al step ''Run tests'' (gate en push a main/develop y PRs). Sincronización inicial: el primer --apply regenera .opencode/scripts/ cerrando el drift de Fase 1 (skalling-metrics.sh summary, teamdb-claim.sh in_review→approved, lib-teamdb.sh CHECK constraint DISCOVERY) en un commit que el gate debe validar.','(1) scripts/build-local-snapshot.sh existe con --apply/--check/--dry-run; (2) scripts/.bundle-manifest lista todos los bundle-esential con sha256 esperado; (3) bash scripts/build-local-snapshot.sh --check retorna 0 sin drift y exit≠0 con drift simulado (test cubre ambos casos); (4) tests/scripts-parity.test.sh pasa local y en CI; (5) bash setup-team-doctor.sh --strict falla con WARN de drift; (6) .github/workflows/tests.yml ejecuta el test en push a main/develop y PRs a main; (7) el commit de sincronización inicial cierra Fase 1 (lib-teamdb.sh CHECK DISCOVERY presente, skalling-metrics.sh summary presente, teamdb-claim.sh validaciones in_review→approved presentes en .opencode/scripts/); (8) tests/install-script-copies.test.sh sigue pasando (instalación global intacta); (9) AGENTS.md incluye sección ''Bundle local .opencode/scripts/'' con contrato, comandos de regeneración y referencia al gate de CI.'||char(10)||char(10)||'Referencia de alcance/aprobación: Plan técnico para Fase 2 del plan de remediación de Skalling. Riesgo medium. request_id req-20260913101348-44357 (clasificado FAST-TRACK pero requiere plan aprobado por la naturaleza medium). Decisión Opción B confirmada por el usuario: generación verificada sin symlinks; cp en install-global.sh se mantiene intacto; agregar tests/scripts-parity.test.sh con diff recursivo scripts/ vs .opencode/scripts/ en CI; check en setup-team-doctor.sh comparando hash de scripts instalados vs fuente del checkout; gate en CI falla si alguien toca scripts/x.sh y no actualiza .opencode/scripts/x.sh.','approved','sol','2026-09-13T13:40:54Z','2026-09-13 13:43:30',NULL,'# Intent'||char(10)||char(10)||'Paridad bundle-local .opencode/scripts/ vs fuente scripts/',2,'sol','sol');
